mapper.select:
select t.departure_time,t.departure_time departureTime,t.msg,t.qrcode,t.status_cd,t.status_cd
statusCd,t.visit_gender,t.visit_gender visitGender,t.owner_id,t.owner_id ownerId,t.room_name,t.room_name
roomName,t.room_id,t.room_id roomId,t.visit_time,t.visit_time visitTime,t.phone_number,t.phone_number
phoneNumber,t.visit_id,t.visit_id visitId,t.owner_name,t.owner_name ownerName,t.name,t.visit_case,t.visit_case
visitCase,t.type_id,t.type_id typeId,t.face_path,t.face_path facePath,t.state,t.community_id,t.community_id
communityId,t.create_time createTime,vt.name visitTypeName,td.name stateName,t.car_num carNum
from visit t
left join visit_type vt on t.type_id = vt.type_id and vt.status_cd = '0'
left join t_dict td on t.state = td.status_cd and td.table_name = 'visit' and td.table_columns = 'state'
where 1 =1

    and t.departure_time= #{departureTime}


    and t.msg= #{msg}


    and t.qrcode= #{qrcode}


    and t.status_cd= #{statusCd}


    and t.visit_gender= #{visitGender}


    and t.owner_id= #{ownerId}


    and t.room_name= #{roomName}


    and t.room_id= #{roomId}


    and t.visit_time= #{visitTime}


    and t.phone_number= #{phoneNumber}


    and t.visit_id= #{visitId}


    and t.owner_name= #{ownerName}


    and t.car_num= #{carNum}


    and t.name= #{name}


    and t.visit_case= #{visitCase}


    and t.type_id= #{typeId}


    and t.face_path= #{facePath}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.name like concat('%', #{nameLike}, '%')


    and t.phone_number like concat('%', #{phoneNumberLike}, '%')


    and t.room_name like concat('%', #{roomNameLike}, '%')


    and t.owner_name like concat('%', #{ownerNameLike}, '%')


    and t.create_time >= #{queryStartTime}


    and t.create_time <= #{queryEndTime}

order by t.create_time desc

    limit #{page}, #{row}

